SELECT distinct TRD_PRODUCT_DEAL.TRADE_ID AS code, TRD_PRODUCT_DEAL_ADD.PORTFOLIO_ID portfolioId FROM TRD_PRODUCT_DEAL INNER JOIN TRD_PRODUCT_DEAL_ADD ON TRD_PRODUCT_DEAL.TRADE_ID = TRD_PRODUCT_DEAL_ADD.TRADE_ID
TRD_PRODUCT_DEAL.FINPROD_TYPE2 = #{FINPROD_TYPE_TG_F23,jdbcType=VARCHAR}
AND TRD_PRODUCT_DEAL.TRADE_ID LIKE CONCAT('%',CONCAT(#{busiNo,jdbcType=VARCHAR},'%'))

SELECT distinct A.PORTFOLIO_ID id, A.PORTFOLIO_NAME text FROM PTL_PORTFOLIO A INNER JOIN PTL_PORTFOLIO_AUTHORITY ON A.PORTFOLIO_ID = PTL_PORTFOLIO_AUTHORITY.PORTFOLIO_ID
A.PORTFOLIO_ID LIKE CONCAT(#{search,jdbcType=VARCHAR},'%') OR A.PORTFOLIO_NAME LIKE CONCAT(#{search,jdbcType=VARCHAR},'%')
AND A.PORTFOLIO_ID = #{initValue,jdbcType=VARCHAR}
AND PTL_PORTFOLIO_AUTHORITY.USER_ID = #{userName}

